SELECT COUNT(DISTINCT m.home_team_api_id) AS distinct_entity_cnt FROM EU_SOCCER.MATCH m;
SELECT m.league_id, COUNT(*) AS event_cnt FROM EU_SOCCER.MATCH m GROUP BY m.league_id ORDER BY event_cnt DESC LIMIT 1000;
SELECT COUNT(*) AS event_cnt FROM EU_SOCCER.MATCH m WHERE CAST(m.date AS DATETIME) >= '2024-01-01 00:00:00' AND CAST(m.date AS DATETIME) < '2024-01-31 23:59:59';
SELECT m.season, COUNT(*) AS event_cnt FROM EU_SOCCER.MATCH m GROUP BY m.season ORDER BY event_cnt DESC LIMIT 1000;
SELECT m.season, AVG(m.B365H) AS avg_home_win_odds FROM EU_SOCCER.MATCH m WHERE m.B365H IS NOT NULL GROUP BY m.season ORDER BY avg_home_win_odds DESC LIMIT 1000;
SELECT m.match_api_id, COUNT(DISTINCT m.home_team_api_id) AS entity_cnt FROM EU_SOCCER.MATCH m GROUP BY m.match_api_id HAVING COUNT(DISTINCT m.home_team_api_id) > 1 ORDER BY entity_cnt DESC LIMIT 3;
WITH a AS ( SELECT DISTINCT ta.team_api_id FROM EU_SOCCER.TEAM_ATTRIBUTES ta WHERE CAST(ta.date AS DATETIME) >= '2012-01-01 00:00:00' AND CAST(ta.date AS DATETIME) < '2013-01-01 00:00:00' ), b AS ( SELECT DISTINCT ta.team_api_id FROM EU_SOCCER.TEAM_ATTRIBUTES ta WHERE CAST(ta.date AS DATETIME) >= '2014-01-01 00:00:00' AND CAST(ta.date AS DATETIME) < '2015-01-01 00:00:00' ) SELECT COUNT(*) AS retained_entity_cnt FROM a JOIN b USING (team_api_id);
SELECT m.season, SUM(CASE WHEN CAST(m.date AS DATETIME) >= '2012-01-01 00:00:00' AND CAST(m.date AS DATETIME) < '2013-01-01 00:00:00' THEN 1 ELSE 0 END) AS curr_cnt, SUM(CASE WHEN CAST(m.date AS DATETIME) >= '2014-01-01 00:00:00' AND CAST(m.date AS DATETIME) < '2015-01-01 00:00:00' THEN 1 ELSE 0 END) AS prev_cnt, ( SUM(CASE WHEN CAST(m.date AS DATETIME) >= '2012-01-01 00:00:00' AND CAST(m.date AS DATETIME) < '2013-01-01 00:00:00' THEN 1 ELSE 0 END) - SUM(CASE WHEN CAST(m.date AS DATETIME) >= '2014-01-01 00:00:00' AND CAST(m.date AS DATETIME) < '2015-01-01 00:00:00' THEN 1 ELSE 0 END) ) AS delta_cnt FROM EU_SOCCER.MATCH m GROUP BY m.season ORDER BY delta_cnt DESC LIMIT 3;
WITH agg AS ( SELECT m.season AS topic, AVG(m.B365H) AS amt FROM EU_SOCCER.MATCH m WHERE m.B365H IS NOT NULL AND CAST(m.date AS DATETIME) >= '2012-01-01 00:00:00' AND CAST(m.date AS DATETIME) < '2013-01-01 00:00:00' GROUP BY m.season ), tot AS ( SELECT SUM(amt) AS total_amt FROM agg ) SELECT topic, amt, amt / NULLIF((SELECT total_amt FROM tot), 0) AS amt_share FROM agg ORDER BY amt_share DESC;
WITH daily AS ( SELECT DATE( CAST(m.date AS DATETIME)) AS d, COUNT(*) AS cnt FROM EU_SOCCER.MATCH m WHERE CAST(m.date AS DATETIME) >= '2012-01-01 00:00:00' AND CAST(m.date AS DATETIME) < '2013-01-01 00:00:00' GROUP BY d ), ma AS ( SELECT d, cnt, AVG(cnt) OVER (ORDER BY d ROWS BETWEEN 7 PRECEDING AND 1 PRECEDING) AS prev_7d_avg FROM daily ) SELECT d, cnt, prev_7d_avg FROM ma WHERE prev_7d_avg IS NOT NULL AND cnt > prev_7d_avg ORDER BY (cnt - prev_7d_avg) DESC LIMIT 3;
SELECT pa.player_api_id, SUM(CASE WHEN pa.attacking_work_rate ='high' or pa.attacking_work_rate ='medium' THEN 1 ELSE 0 END) AS hit_cnt, COUNT(*) AS total_cnt, SUM(CASE WHEN pa.attacking_work_rate ='high' or pa.attacking_work_rate ='medium' THEN 1 ELSE 0 END) / COUNT(*) AS hit_ratio FROM EU_SOCCER.PLAYER_ATTRIBUTES pa GROUP BY pa.player_api_id HAVING COUNT(*) >= 1 ORDER BY hit_ratio DESC LIMIT 3;
SELECT pa.id, COUNT(DISTINCT pa.player_api_id) AS external_cnt FROM EU_SOCCER.PLAYER_ATTRIBUTES pa GROUP BY pa.id HAVING COUNT(DISTINCT pa.player_api_id) > 1 ORDER BY external_cnt DESC LIMIT 10;
WITH agg AS ( SELECT ta.buildUpPlaySpeedClass AS topic, t.team_long_name AS entity_name, COUNT(*) AS qty FROM EU_SOCCER.TEAM_ATTRIBUTES ta JOIN EU_SOCCER.TEAM t ON ta.team_api_id = t.team_api_id GROUP BY ta.buildUpPlaySpeedClass, t.team_long_name ), ranked AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY topic ORDER BY qty DESC, entity_name) AS rn FROM agg ) SELECT topic, entity_name, qty FROM ranked WHERE rn = 1 ORDER BY qty DESC;
SELECT c.name AS location, m.season AS category_topic, COUNT(*) AS event_cnt FROM EU_SOCCER.MATCH m JOIN EU_SOCCER.LEAGUE l ON m.league_id = l.id JOIN EU_SOCCER.COUNTRY c ON l.country_id = c.id GROUP BY c.name, m.season HAVING COUNT(*) >= 5 ORDER BY event_cnt DESC LIMIT 20;
SELECT COUNT(DISTINCT fie.FEDERAL_REGULATOR) AS distinct_entity_cnt FROM FINANCE__ECONOMICS.CYBERSYN_FINANCIAL_INSTITUTION_ENTITIES fie;
SELECT c.ID_STATE, COUNT(*) AS event_cnt FROM FINANCE__ECONOMICS.CYBERSYN_FINANCIAL_CFPB_COMPLAINT c GROUP BY c.ID_STATE ORDER BY event_cnt DESC LIMIT 1000;
SELECT COUNT(*) AS event_cnt FROM FINANCE__ECONOMICS.CYBERSYN_FINANCIAL_CFPB_COMPLAINT c WHERE c.DATE_RECEIVED >= '2024-01-01 00:00:00' AND c.DATE_RECEIVED < '2024-01-31 23:59:59';
SELECT c.PRODUCT, COUNT(*) AS event_cnt FROM FINANCE__ECONOMICS.CYBERSYN_FINANCIAL_CFPB_COMPLAINT c GROUP BY c.PRODUCT ORDER BY event_cnt DESC LIMIT 1000;
SELECT s.ASSET_CLASS, SUM(s.VALUE) AS total_amount FROM FINANCE__ECONOMICS.CYBERSYN_STOCK_PRICE_TIMESERIES s GROUP BY s.ASSET_CLASS ORDER BY total_amount DESC LIMIT 1000;
SELECT e.ID_RSSD_PREDECESSOR, COUNT(DISTINCT e.CATEGORY_SUCCESSOR) AS entity_cnt FROM FINANCE__ECONOMICS.CYBERSYN_FINANCIAL_INSTITUTION_EVENTS e GROUP BY e.ID_RSSD_PREDECESSOR HAVING COUNT(DISTINCT e.CATEGORY_SUCCESSOR) > 1 ORDER BY entity_cnt DESC LIMIT 3;
WITH a AS ( SELECT DISTINCT t.ID_RSSD FROM FINANCE__ECONOMICS.CYBERSYN_FINANCIAL_INSTITUTION_TIMESERIES t WHERE t.DATE >= '2025-06-01' AND t.DATE < '2025-07-01' ), b AS ( SELECT DISTINCT t.ID_RSSD FROM FINANCE__ECONOMICS.CYBERSYN_FINANCIAL_INSTITUTION_TIMESERIES t WHERE t.DATE >= '2025-12-01' AND t.DATE < '2026-01-01' ) SELECT COUNT(*) AS retained_entity_cnt FROM a JOIN b USING (ID_RSSD);
WITH agg AS ( SELECT s.ASSET_CLASS AS topic, SUM(s.VALUE) AS amt FROM FINANCE__ECONOMICS.CYBERSYN_STOCK_PRICE_TIMESERIES s WHERE CAST(s.DATE AS DATETIME) >= '2024-11-01' AND CAST(s.DATE AS DATETIME) < '2024-12-01' GROUP BY s.ASSET_CLASS ), tot AS ( SELECT SUM(amt) AS total_amt FROM agg ) SELECT topic, amt, amt / NULLIF((SELECT total_amt FROM tot), 0) AS amt_share FROM agg ORDER BY amt_share DESC;
WITH daily AS ( SELECT DATE( c.DATE_RECEIVED) AS d, COUNT(*) AS cnt FROM FINANCE__ECONOMICS.CYBERSYN_FINANCIAL_CFPB_COMPLAINT c WHERE CAST(c.DATE_RECEIVED AS DATETIME) >= '2024-07-01' AND CAST(c.DATE_RECEIVED AS DATETIME) < '2024-07-31' GROUP BY d ), ma AS ( SELECT d, cnt, AVG(cnt) OVER (ORDER BY d ROWS BETWEEN 7 PRECEDING AND 1 PRECEDING) AS prev_7d_avg FROM daily ) SELECT d, cnt, prev_7d_avg FROM ma WHERE prev_7d_avg IS NOT NULL AND cnt > prev_7d_avg ORDER BY (cnt - prev_7d_avg) DESC;
SELECT c.ID_STATE, SUM(CASE WHEN c.TIMELY_RESPONSE = 1 THEN 1 ELSE 0 END) AS hit_cnt, COUNT(*) AS total_cnt, SUM(CASE WHEN c.TIMELY_RESPONSE = 1 THEN 1 ELSE 0 END) / COUNT(*) AS hit_ratio FROM FINANCE__ECONOMICS.CYBERSYN_FINANCIAL_CFPB_COMPLAINT c GROUP BY c.ID_STATE HAVING COUNT(*) >= 50 ORDER BY hit_ratio DESC LIMIT 3;
SELECT ci.COMPANY_ID, COUNT(DISTINCT ci.PERMID_COMPANY_ID) AS external_cnt FROM FINANCE__ECONOMICS.CYBERSYN_COMPANY_INDEX ci GROUP BY ci.COMPANY_ID HAVING COUNT(DISTINCT ci.PERMID_COMPANY_ID) > 1 ORDER BY external_cnt DESC LIMIT 10;
SELECT c.ID_ZIP FROM FINANCE__ECONOMICS.CYBERSYN_FINANCIAL_CFPB_COMPLAINT c WHERE c.CONSUMER_COMPLAINT_NARRATIVE LIKE '%fraud%' or '%collection%' or '%identity theft%' LIMIT 5;
SELECT c.PRODUCT, COUNT(*) AS event_cnt FROM FINANCE__ECONOMICS.CYBERSYN_FINANCIAL_CFPB_COMPLAINT c WHERE str_to_date(c.DATE_RECEIVED,'%Y-%m-%d') >= '2024-01-01' AND str_to_date(c.DATE_RECEIVED,'%Y-%m-%d') < '2026-01-01' AND c.CONSUMER_COMPLAINT_NARRATIVE LIKE '%fraud%' or '%harassment%' or '%identity theft%' GROUP BY c.PRODUCT ORDER BY event_cnt DESC LIMIT 10;
SELECT c.STATE, c.PRODUCT, COUNT(*) AS event_cnt FROM FINANCE__ECONOMICS.CYBERSYN_FINANCIAL_CFPB_COMPLAINT c GROUP BY c.STATE, c.PRODUCT HAVING COUNT(*) >= 5 ORDER BY event_cnt DESC LIMIT 20;
SELECT COUNT(DISTINCT s.prod_id) AS distinct_entity_cnt FROM COMPLEX_ORACLE.SALES s;
SELECT c.country_id, COUNT(*) AS event_cnt FROM COMPLEX_ORACLE.CUSTOMERS c GROUP BY c.country_id ORDER BY event_cnt DESC LIMIT 1000;
SELECT COUNT(*) AS event_cnt FROM COMPLEX_ORACLE.SALES s JOIN COMPLEX_ORACLE.CUSTOMERS c ON s.cust_id = c.cust_id WHERE CAST(s.time_id AS DATE) >= '2024-01-01 00:00:00' AND CAST(s.time_id AS DATE) < '2024-01-31 23:59:59';
SELECT p.promo_category, COUNT(*) AS event_cnt FROM COMPLEX_ORACLE.SALES s JOIN COMPLEX_ORACLE.PROMOTIONS p ON s.promo_id = p.promo_id GROUP BY p.promo_category ORDER BY event_cnt DESC LIMIT 1000;
SELECT p.promo_category, SUM(s.amount_sold) AS total_amount FROM COMPLEX_ORACLE.SALES s JOIN COMPLEX_ORACLE.PROMOTIONS p ON s.promo_id = p.promo_id GROUP BY p.promo_category ORDER BY total_amount DESC LIMIT 1000;
WITH a AS ( SELECT DISTINCT s.prod_id FROM COMPLEX_ORACLE.SALES s JOIN COMPLEX_ORACLE.PROMOTIONS p ON s.promo_id = p.promo_id WHERE CAST(s.time_id AS DATE) >= '2019-03-01' AND CAST(s.time_id AS DATE) < '2019-03-11' ), b AS ( SELECT DISTINCT s.prod_id FROM COMPLEX_ORACLE.SALES s JOIN COMPLEX_ORACLE.PROMOTIONS p ON s.promo_id = p.promo_id WHERE CAST(s.time_id AS DATE) >= '2019-03-20' AND CAST(s.time_id AS DATE) < '2019-04-01' ) SELECT COUNT(*) AS retained_entity_cnt FROM a JOIN b USING (prod_id);
SELECT p.promo_category, SUM(CASE WHEN CAST(s.time_id AS DATE) >= '2019-03-01' AND CAST(s.time_id AS DATE) < '2019-03-11' THEN 1 ELSE 0 END) AS curr_cnt, SUM(CASE WHEN CAST(s.time_id AS DATE) >= '2019-03-20' AND CAST(s.time_id AS DATE) < '2019-04-01' THEN 1 ELSE 0 END) AS prev_cnt, ( SUM(CASE WHEN CAST(s.time_id AS DATE) >= '2019-03-01' AND CAST(s.time_id AS DATE) < '2019-03-11' THEN 1 ELSE 0 END) - SUM(CASE WHEN CAST(s.time_id AS DATE) >= '2019-03-20' AND CAST(s.time_id AS DATE) < '2019-04-01' THEN 1 ELSE 0 END) ) AS delta_cnt FROM COMPLEX_ORACLE.SALES s JOIN COMPLEX_ORACLE.PROMOTIONS p ON s.promo_id = p.promo_id GROUP BY p.promo_category ORDER BY delta_cnt DESC LIMIT 3;
WITH agg AS ( SELECT p.promo_category AS topic, SUM(s.amount_sold) AS amt FROM COMPLEX_ORACLE.SALES s JOIN COMPLEX_ORACLE.PROMOTIONS p ON s.promo_id = p.promo_id WHERE CAST(s.time_id AS DATE) >= '2019-03-01' AND CAST(s.time_id AS DATE) < '2019-03-11' GROUP BY p.promo_category ), tot AS ( SELECT SUM(amt) AS total_amt FROM agg ) SELECT topic, amt, amt / NULLIF((SELECT total_amt FROM tot), 0) AS amt_share FROM agg ORDER BY amt_share DESC;
WITH daily AS ( SELECT DATE( CAST(s.time_id AS DATE)) AS d, COUNT(*) AS cnt FROM COMPLEX_ORACLE.SALES s JOIN COMPLEX_ORACLE.CUSTOMERS c ON s.cust_id = c.cust_id WHERE CAST(s.time_id AS DATE) >= '2019-03-20' AND CAST(s.time_id AS DATE) < '2019-04-01' GROUP BY d ), ma AS ( SELECT d, cnt, AVG(cnt) OVER (ORDER BY d ROWS BETWEEN 7 PRECEDING AND 1 PRECEDING) AS prev_7d_avg FROM daily ) SELECT d, cnt, prev_7d_avg FROM ma WHERE prev_7d_avg IS NOT NULL AND cnt > prev_7d_avg ORDER BY (cnt - prev_7d_avg) DESC LIMIT 3;
SELECT p.prod_id, COUNT(DISTINCT p.prod_src_id) AS external_cnt FROM COMPLEX_ORACLE.PRODUCTS p GROUP BY p.prod_id HAVING COUNT(DISTINCT p.prod_src_id) > 1 ORDER BY external_cnt DESC LIMIT 10;
WITH agg AS ( SELECT c.channel_class AS topic, c.channel_desc AS entity_name, SUM(s.quantity_sold) AS qty FROM COMPLEX_ORACLE.SALES s JOIN COMPLEX_ORACLE.CHANNELS c ON s.channel_id = c.channel_id GROUP BY c.channel_class, c.channel_desc ), ranked AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY topic ORDER BY qty DESC, entity_name) AS rn FROM agg ) SELECT topic, entity_name, qty FROM ranked WHERE rn = 1 ORDER BY qty DESC;
SELECT COUNT(DISTINCT d.OwnerOrganizationId) AS distinct_entity_cnt FROM META_KAGGLE.DATASETS d WHERE d.OwnerOrganizationId IS NOT NULL;
SELECT dt.OwnerUserId, COUNT(*) AS event_cnt FROM META_KAGGLE.DATASETTASKS dt GROUP BY dt.OwnerUserId ORDER BY event_cnt DESC LIMIT 1000;
SELECT COUNT(*) AS event_cnt FROM META_KAGGLE.KERNELVOTES kv WHERE kv.VoteDate >= '2024-01-01 00:00:00' AND kv.VoteDate < '2024-01-31 23:59:59';
SELECT c.RewardType, COUNT(*) AS event_cnt FROM META_KAGGLE.COMPETITIONS c GROUP BY c.RewardType ORDER BY event_cnt DESC LIMIT 1000;
SELECT ea.State, SUM(ea.Reward) AS total_amount FROM META_KAGGLE.EPISODEAGENTS ea GROUP BY ea.State ORDER BY total_amount DESC LIMIT 1000;
SELECT ct.CompetitionId, COUNT(DISTINCT ct.TagId) AS entity_cnt FROM META_KAGGLE.COMPETITIONTAGS ct GROUP BY ct.CompetitionId HAVING COUNT(DISTINCT ct.TagId) > 1 ORDER BY entity_cnt DESC LIMIT 3;
WITH a AS ( SELECT DISTINCT k.AuthorUserId FROM META_KAGGLE.KERNELS k WHERE k.MadePublicDate >= '2022-07-01' AND k.MadePublicDate < '2022-09-01' ), b AS ( SELECT DISTINCT k.AuthorUserId FROM META_KAGGLE.KERNELS k WHERE k.MadePublicDate >= '2023-07-01' AND k.MadePublicDate < '2023-09-01' ) SELECT COUNT(*) AS retained_entity_cnt FROM a JOIN b USING (AuthorUserId);
WITH agg AS ( SELECT ea.State AS topic, SUM(ea.Reward) AS amt FROM META_KAGGLE.EPISODEAGENTS ea JOIN META_KAGGLE.EPISODES e ON ea.EpisodeId = e.Id WHERE e.EndTime >= '2020-09-01' AND e.EndTime < '2020-09-30' GROUP BY ea.State ), tot AS ( SELECT SUM(amt) AS total_amt FROM agg ) SELECT topic, amt, amt / NULLIF((SELECT total_amt FROM tot), 0) AS amt_share FROM agg ORDER BY amt_share DESC;
WITH daily AS ( SELECT DATE( kv.VoteDate) AS d, COUNT(*) AS cnt FROM META_KAGGLE.KERNELVOTES kv WHERE CAST(kv.VoteDate AS DATETIME) >= '2019-07-01' AND CAST(kv.VoteDate AS DATETIME) < '2019-07-08' GROUP BY d ), ma AS ( SELECT d, cnt, AVG(cnt) OVER (ORDER BY d ROWS BETWEEN 7 PRECEDING AND 1 PRECEDING) AS prev_7d_avg FROM daily ) SELECT d, cnt, prev_7d_avg FROM ma WHERE prev_7d_avg IS NOT NULL AND cnt > prev_7d_avg ORDER BY (cnt - prev_7d_avg) DESC;
SELECT ea.EpisodeId, SUM(CASE WHEN ea.State = '2' THEN 1 ELSE 0 END) AS hit_cnt, COUNT(*) AS total_cnt, SUM(CASE WHEN ea.State = '2' THEN 1 ELSE 0 END) / COUNT(*) AS hit_ratio FROM META_KAGGLE.EPISODEAGENTS ea GROUP BY ea.EpisodeId HAVING COUNT(*) >= 1 ORDER BY hit_ratio DESC LIMIT 3;
SELECT d.Id, COUNT(DISTINCT d.CurrentDatasetVersionId) AS external_cnt FROM META_KAGGLE.DATASETS d GROUP BY d.Id HAVING COUNT(DISTINCT d.CurrentDatasetVersionId) > 1 ORDER BY external_cnt DESC LIMIT 10;
SELECT fm.ForumTopicId AS id_external FROM META_KAGGLE.FORUMMESSAGES fm WHERE COALESCE(fm.RawMarkdown, '') LIKE '%bug%' or '%submission%' or '%GPU%' LIMIT 5;
WITH agg AS ( SELECT c.RewardType AS topic, c.EvaluationAlgorithmName AS entity_name, COUNT(*) AS qty FROM META_KAGGLE.COMPETITIONS c WHERE c.EvaluationAlgorithmName IS NOT NULL GROUP BY c.RewardType, c.EvaluationAlgorithmName ), ranked AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY topic ORDER BY qty DESC, entity_name) AS rn FROM agg ) SELECT topic, entity_name, qty FROM ranked WHERE rn = 1 ORDER BY qty DESC;
SELECT fm.ForumTopicId AS category_topic, COUNT(*) AS event_cnt FROM META_KAGGLE.FORUMMESSAGES fm WHERE str_to_date(fm.PostDate, '%m/%d/%Y %H:%i:%s') >= '2021-01-01' AND str_to_date(fm.PostDate, '%m/%d/%Y %H:%i:%s') < '2024-01-01' AND COALESCE(fm.RawMarkdown, '') LIKE '%submission error%' or '%GPU%' or '%dataset link%' GROUP BY fm.ForumTopicId ORDER BY event_cnt DESC LIMIT 10;
SELECT COUNT(DISTINCT oi.seller_id) AS distinct_entity_cnt FROM BRAZILIAN_E_COMMERCE.OLIST_ORDER_ITEMS oi;
SELECT oi.seller_id, COUNT(*) AS event_cnt FROM BRAZILIAN_E_COMMERCE.OLIST_ORDERS o JOIN BRAZILIAN_E_COMMERCE.OLIST_ORDER_ITEMS oi ON o.order_id = oi.order_id GROUP BY oi.seller_id ORDER BY event_cnt DESC LIMIT 1000;
SELECT COUNT(*) AS event_cnt FROM BRAZILIAN_E_COMMERCE.OLIST_ORDERS o WHERE CAST(o.order_purchase_timestamp AS DATETIME) >= '2024-01-01 00:00:00' AND CAST(o.order_purchase_timestamp AS DATETIME) < '2024-01-31 23:59:59';
SELECT op.payment_type, COUNT(*) AS event_cnt FROM BRAZILIAN_E_COMMERCE.OLIST_ORDER_PAYMENTS op JOIN BRAZILIAN_E_COMMERCE.OLIST_ORDERS o ON op.order_id = o.order_id GROUP BY op.payment_type ORDER BY event_cnt DESC LIMIT 1000;
SELECT op.payment_type, SUM(op.payment_value) AS total_amount FROM BRAZILIAN_E_COMMERCE.OLIST_ORDER_PAYMENTS op GROUP BY op.payment_type ORDER BY total_amount DESC LIMIT 1000;
SELECT o.order_id, COUNT(DISTINCT oi.seller_id) AS entity_cnt FROM BRAZILIAN_E_COMMERCE.OLIST_ORDERS o JOIN BRAZILIAN_E_COMMERCE.OLIST_ORDER_ITEMS oi ON o.order_id = oi.order_id GROUP BY o.order_id HAVING COUNT(DISTINCT oi.seller_id) > 1 ORDER BY entity_cnt DESC LIMIT 3;
WITH a AS ( SELECT DISTINCT oi.seller_id FROM BRAZILIAN_E_COMMERCE.OLIST_ORDERS o JOIN BRAZILIAN_E_COMMERCE.OLIST_ORDER_ITEMS oi ON o.order_id = oi.order_id WHERE CAST(o.order_purchase_timestamp AS DATETIME) >= '2018-06-01 13:00:00' AND CAST(o.order_purchase_timestamp AS DATETIME) < '2018-06-01 15:00:00' ), b AS ( SELECT DISTINCT oi.seller_id FROM BRAZILIAN_E_COMMERCE.OLIST_ORDERS o JOIN BRAZILIAN_E_COMMERCE.OLIST_ORDER_ITEMS oi ON o.order_id = oi.order_id WHERE CAST(o.order_purchase_timestamp AS DATETIME) >= '2018-06-01 17:00:00' AND CAST(o.order_purchase_timestamp AS DATETIME) < '2018-06-01 19:00:00' ) SELECT COUNT(*) AS retained_entity_cnt FROM a JOIN b USING (seller_id);
SELECT op.payment_type, SUM(CASE WHEN CAST(o.order_purchase_timestamp AS DATETIME) >= '2018-06-01 13:00:00' AND CAST(o.order_purchase_timestamp AS DATETIME) < '2018-06-01 15:00:00' THEN 1 ELSE 0 END) AS curr_cnt, SUM(CASE WHEN CAST(o.order_purchase_timestamp AS DATETIME) >= '2018-06-01 17:00:00' AND CAST(o.order_purchase_timestamp AS DATETIME) < '2018-06-01 19:00:00' THEN 1 ELSE 0 END) AS prev_cnt, SUM(CASE WHEN CAST(o.order_purchase_timestamp AS DATETIME) >= '2018-06-01 13:00:00' AND CAST(o.order_purchase_timestamp AS DATETIME) < '2018-06-01 15:00:00' THEN 1 ELSE 0 END) - SUM(CASE WHEN CAST(o.order_purchase_timestamp AS DATETIME) >= '2018-06-01 17:00:00' AND CAST(o.order_purchase_timestamp AS DATETIME) < '2018-06-01 19:00:00' THEN 1 ELSE 0 END) AS delta_cnt FROM BRAZILIAN_E_COMMERCE.OLIST_ORDER_PAYMENTS op JOIN BRAZILIAN_E_COMMERCE.OLIST_ORDERS o ON op.order_id = o.order_id GROUP BY op.payment_type ORDER BY delta_cnt DESC LIMIT 3;
WITH agg AS ( SELECT op.payment_type AS topic, SUM(op.payment_value) AS amt FROM BRAZILIAN_E_COMMERCE.OLIST_ORDER_PAYMENTS op JOIN BRAZILIAN_E_COMMERCE.OLIST_ORDERS o ON op.order_id = o.order_id WHERE CAST(o.order_purchase_timestamp AS DATETIME) >= '2018-05-23 15:00:00' AND CAST(o.order_purchase_timestamp AS DATETIME) < '2018-05-23 17:00:00' GROUP BY op.payment_type ), tot AS ( SELECT SUM(amt) AS total_amt FROM agg ) SELECT topic, amt, amt / NULLIF((SELECT total_amt FROM tot), 0) AS amt_share FROM agg ORDER BY amt_share DESC;
WITH daily AS ( SELECT DATE( CAST(o.order_purchase_timestamp AS DATETIME)) AS d, COUNT(*) AS cnt FROM BRAZILIAN_E_COMMERCE.OLIST_ORDERS o WHERE CAST(o.order_purchase_timestamp AS DATETIME) >= '2018-02-01 00:00:00' AND CAST(o.order_purchase_timestamp AS DATETIME) < '2018-02-07 00:00:00' GROUP BY d ), ma AS ( SELECT d, cnt, AVG(cnt) OVER (ORDER BY d ROWS BETWEEN 7 PRECEDING AND 1 PRECEDING) AS prev_7d_avg FROM daily ) SELECT d, cnt, prev_7d_avg FROM ma WHERE prev_7d_avg IS NOT NULL AND cnt > prev_7d_avg ORDER BY (cnt - prev_7d_avg) DESC;
SELECT oi.seller_id, SUM(CASE WHEN o.order_status = 'delivered' THEN 1 ELSE 0 END) AS hit_cnt, COUNT(*) AS total_cnt, SUM(CASE WHEN o.order_status = 'delivered' THEN 1 ELSE 0 END) / COUNT(*) AS hit_ratio FROM BRAZILIAN_E_COMMERCE.OLIST_ORDERS o JOIN BRAZILIAN_E_COMMERCE.OLIST_ORDER_ITEMS oi ON o.order_id = oi.order_id GROUP BY oi.seller_id HAVING COUNT(*) >= 2 ORDER BY hit_ratio DESC LIMIT 3;
SELECT c.customer_id, COUNT(DISTINCT c.customer_unique_id) AS external_cnt FROM BRAZILIAN_E_COMMERCE.OLIST_CUSTOMERS c GROUP BY c.customer_id HAVING COUNT(DISTINCT c.customer_unique_id) > 1 ORDER BY external_cnt DESC LIMIT 10;
SELECT COUNT(DISTINCT ms.product_id) AS distinct_entity_cnt FROM ORACLE_SQL.MONTHLY_SALES ms;
SELECT o.ORDERID, COUNT(*) AS event_cnt FROM ORACLE_SQL.ORDERS o WHERE o.ORDERID IS NOT NULL GROUP BY o.ORDERID ORDER BY event_cnt DESC LIMIT 1000;
SELECT COUNT(*) AS event_cnt FROM ORACLE_SQL.ORDERS o WHERE STR_TO_DATE(o.ORDERID, '%Y-%m-%d') >= '2024-01-01' AND STR_TO_DATE(o.ORDERID, '%Y-%m-%d') < '2024-01-31';
SELECT t.symbol, COUNT(*) AS event_cnt FROM ORACLE_SQL.TICKER t WHERE t.symbol IS NOT NULL GROUP BY t.symbol ORDER BY event_cnt DESC LIMIT 1000;
SELECT p.PRODUCTID, SUM(p.PURCHASEDATE) AS total_amount FROM ORACLE_SQL.PURCHASES p WHERE p.PRODUCTID IS NOT NULL AND p.PURCHASEDATE IS NOT NULL GROUP BY p.PRODUCTID ORDER BY total_amount DESC LIMIT 1000;
SELECT ol.ORDERID, COUNT(DISTINCT ol.PRODUCTID) AS entity_cnt FROM ORACLE_SQL.ORDERLINES ol GROUP BY ol.ORDERID HAVING COUNT(DISTINCT ol.PRODUCTID) > 1 ORDER BY entity_cnt DESC LIMIT 3;
WITH a AS ( SELECT DISTINCT ms.product_id FROM ORACLE_SQL.MONTHLY_SALES ms WHERE STR_TO_DATE(ms.mth, '%Y-%m-%d') >= '2018-01-01' AND STR_TO_DATE(ms.mth, '%Y-%m-%d') < '2018-04-01' ), b AS ( SELECT DISTINCT ms.product_id FROM ORACLE_SQL.MONTHLY_SALES ms WHERE STR_TO_DATE(ms.mth, '%Y-%m-%d') >= '2018-10-01' AND STR_TO_DATE(ms.mth, '%Y-%m-%d') < '2019-01-01' ) SELECT COUNT(*) AS retained_entity_cnt FROM a JOIN b USING (product_id);
WITH daily AS ( SELECT DATE(STR_TO_DATE(v.visit_time, '%Y-%m-%d %H:%i:%s')) AS d, COUNT(*) AS cnt FROM `ORACLE_SQL`.`WEB_PAGE_VISITS` v WHERE STR_TO_DATE(v.visit_time, '%Y-%m-%d %H:%i:%s') >= '2019-01-01' AND STR_TO_DATE(v.visit_time, '%Y-%m-%d %H:%i:%s') < '2019-07-01' GROUP BY DATE(STR_TO_DATE(v.visit_time, '%Y-%m-%d %H:%i:%s')) ), ma AS ( SELECT d, cnt, AVG(cnt) OVER (ORDER BY d ROWS BETWEEN 7 PRECEDING AND 1 PRECEDING) AS prev_7d_avg FROM daily ) SELECT d, cnt, prev_7d_avg FROM ma WHERE prev_7d_avg IS NOT NULL AND cnt > prev_7d_avg ORDER BY (cnt - prev_7d_avg) DESC LIMIT 3;
SELECT p.app_id, COUNT(DISTINCT p.page_no) AS external_cnt FROM ORACLE_SQL.WEB_PAGES p GROUP BY p.app_id HAVING COUNT(DISTINCT p.page_no) > 1 ORDER BY external_cnt DESC LIMIT 10;
WITH agg AS ( SELECT pg.name AS topic, p.name AS entity_name, COUNT(*) AS qty FROM ORACLE_SQL.PRODUCTS p JOIN ORACLE_SQL.PRODUCT_GROUPS pg ON p.group_id = pg.id GROUP BY pg.name, p.name ), ranked AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY topic ORDER BY qty DESC, entity_name) AS rn FROM agg ) SELECT topic, entity_name, qty FROM ranked WHERE rn = 1 ORDER BY qty DESC;
SELECT v.client_ip AS location, v.app_id AS category_topic, COUNT(*) AS event_cnt FROM ORACLE_SQL.WEB_PAGE_VISITS v GROUP BY v.client_ip, v.app_id HAVING COUNT(*) >= 10 ORDER BY event_cnt DESC LIMIT 20;
SELECT COUNT(DISTINCT ii.product_distribution_center_id) AS distinct_entity_cnt FROM THELOOK_ECOMMERCE.INVENTORY_ITEMS ii WHERE ii.product_distribution_center_id IS NOT NULL;
SELECT ii.product_distribution_center_id, COUNT(*) AS event_cnt FROM THELOOK_ECOMMERCE.INVENTORY_ITEMS ii WHERE ii.product_distribution_center_id IS NOT NULL AND ii.product_sku IS NOT NULL GROUP BY ii.product_distribution_center_id ORDER BY event_cnt DESC LIMIT 1000;
SELECT COUNT(*) AS event_cnt FROM THELOOK_ECOMMERCE.INVENTORY_ITEMS ii WHERE FROM_UNIXTIME(ii.sold_at / 1000000) >= '2024-01-01 00:00:00' AND FROM_UNIXTIME(ii.sold_at / 1000000) < '2024-01-31 23:59:59';
SELECT ii.product_category, COUNT(*) AS event_cnt FROM THELOOK_ECOMMERCE.INVENTORY_ITEMS ii WHERE ii.product_category IS NOT NULL GROUP BY ii.product_category ORDER BY event_cnt DESC LIMIT 1000;
SELECT ii.product_department, SUM(ii.product_retail_price) AS total_amount FROM THELOOK_ECOMMERCE.INVENTORY_ITEMS ii WHERE ii.product_department IS NOT NULL AND ii.product_retail_price IS NOT NULL GROUP BY ii.product_department ORDER BY total_amount DESC LIMIT 1000;
SELECT p.sku, COUNT(DISTINCT p.distribution_center_id) AS entity_cnt FROM THELOOK_ECOMMERCE.PRODUCTS p WHERE p.sku IS NOT NULL GROUP BY p.sku HAVING COUNT(DISTINCT p.distribution_center_id) > 1 ORDER BY entity_cnt DESC LIMIT 3;
WITH a AS ( SELECT DISTINCT ii.product_distribution_center_id FROM THELOOK_ECOMMERCE.INVENTORY_ITEMS ii WHERE ii.product_distribution_center_id IS NOT NULL AND FROM_UNIXTIME(ii.sold_at / 1000000) >= '2023-01-14 10:00:00' AND FROM_UNIXTIME(ii.sold_at / 1000000) < '2023-01-14 11:00:00' ), b AS ( SELECT DISTINCT ii.product_distribution_center_id FROM THELOOK_ECOMMERCE.INVENTORY_ITEMS ii WHERE ii.product_distribution_center_id IS NOT NULL AND FROM_UNIXTIME(ii.sold_at / 1000000) >= '2023-01-14 13:00:00' AND FROM_UNIXTIME(ii.sold_at / 1000000) < '2023-01-14 14:00:00' ) SELECT COUNT(*) AS retained_entity_cnt FROM a JOIN b USING (product_distribution_center_id);
SELECT ii.product_category, SUM(CASE WHEN FROM_UNIXTIME(ii.sold_at / 1000000) >= '2023-01-14 10:00:00' AND FROM_UNIXTIME(ii.sold_at / 1000000) < '2023-01-14 11:00:00' THEN 1 ELSE 0 END) AS curr_cnt, SUM(CASE WHEN FROM_UNIXTIME(ii.sold_at / 1000000) >= '2023-01-14 13:00:00' AND FROM_UNIXTIME(ii.sold_at / 1000000) < '2023-01-14 14:00:00' THEN 1 ELSE 0 END) AS prev_cnt, ( SUM(CASE WHEN FROM_UNIXTIME(ii.sold_at / 1000000) >= '2023-01-14 10:00:00' AND FROM_UNIXTIME(ii.sold_at / 1000000) < '2023-01-14 11:00:00' THEN 1 ELSE 0 END) - SUM(CASE WHEN FROM_UNIXTIME(ii.sold_at / 1000000) >= '2023-01-14 13:00:00' AND FROM_UNIXTIME(ii.sold_at / 1000000) < '2023-01-14 14:00:00' THEN 1 ELSE 0 END) ) AS delta_cnt FROM THELOOK_ECOMMERCE.INVENTORY_ITEMS ii WHERE ii.product_category IS NOT NULL GROUP BY ii.product_category ORDER BY delta_cnt DESC LIMIT 3;
WITH agg AS ( SELECT ii.product_department AS topic, SUM(ii.product_retail_price) AS amt FROM THELOOK_ECOMMERCE.INVENTORY_ITEMS ii WHERE FROM_UNIXTIME(ii.sold_at / 1000000) >= '2023-02-01 00:00:00' AND FROM_UNIXTIME(ii.sold_at / 1000000) < '2023-04-01 00:00:00' AND ii.product_department IS NOT NULL GROUP BY ii.product_department ), tot AS ( SELECT SUM(amt) AS total_amt FROM agg ) SELECT topic, amt, amt / NULLIF((SELECT total_amt FROM tot), 0) AS amt_share FROM agg ORDER BY amt_share DESC;
WITH daily AS ( SELECT DATE( FROM_UNIXTIME(ii.sold_at / 1000000)) AS d, COUNT(*) AS cnt FROM THELOOK_ECOMMERCE.INVENTORY_ITEMS ii WHERE FROM_UNIXTIME(ii.sold_at / 1000000) >= '2023-07-10 00:00:00' AND FROM_UNIXTIME(ii.sold_at / 1000000) < '2023-07-24 00:00:00' GROUP BY d ), ma AS ( SELECT d, cnt, AVG(cnt) OVER (ORDER BY d ROWS BETWEEN 7 PRECEDING AND 1 PRECEDING) AS prev_7d_avg FROM daily ) SELECT d, cnt, prev_7d_avg FROM ma WHERE prev_7d_avg IS NOT NULL AND cnt > prev_7d_avg ORDER BY (cnt - prev_7d_avg) DESC;
SELECT o.user_id, SUM(CASE WHEN o.status = 'Cancelled' THEN 1 ELSE 0 END) AS hit_cnt, COUNT(*) AS total_cnt, SUM(CASE WHEN o.status = 'Cancelled' THEN 1 ELSE 0 END) / COUNT(*) AS hit_ratio FROM THELOOK_ECOMMERCE.ORDERS o WHERE o.user_id IS NOT NULL GROUP BY o.user_id HAVING COUNT(*) >= 10 ORDER BY hit_ratio DESC LIMIT 3;
SELECT p.id, COUNT(DISTINCT p.sku) AS external_cnt FROM THELOOK_ECOMMERCE.PRODUCTS p GROUP BY p.id HAVING COUNT(DISTINCT p.sku) > 1 ORDER BY external_cnt DESC LIMIT 10;
WITH agg AS ( SELECT ii.product_category AS topic, ii.product_brand AS entity_name, SUM(ii.product_retail_price) AS amt FROM THELOOK_ECOMMERCE.INVENTORY_ITEMS ii WHERE ii.product_category IS NOT NULL AND ii.product_brand IS NOT NULL AND ii.product_retail_price IS NOT NULL GROUP BY ii.product_category, ii.product_brand ), ranked AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY topic ORDER BY amt DESC, entity_name) AS rn FROM agg ) SELECT topic, entity_name, amt FROM ranked WHERE rn = 1 ORDER BY amt DESC;
SELECT dc.name AS location, ii.product_department AS category_topic, COUNT(*) AS event_cnt FROM THELOOK_ECOMMERCE.INVENTORY_ITEMS ii JOIN THELOOK_ECOMMERCE.DISTRIBUTION_CENTERS dc ON ii.product_distribution_center_id = dc.id WHERE dc.name IS NOT NULL AND ii.product_department IS NOT NULL GROUP BY dc.name, ii.product_department HAVING COUNT(*) >= 5 ORDER BY event_cnt DESC LIMIT 20;
SELECT COUNT(DISTINCT zt.FromZipCode) AS distinct_entity_cnt FROM CENSUS_GALAXY__ZIP_CODE_TO_BLOCK_GROUP_SAMPLE.XREF_ZIPTOTRACT_RESIDENTIAL zt;
SELECT zt.FromZipCode, COUNT(*) AS event_cnt FROM CENSUS_GALAXY__ZIP_CODE_TO_BLOCK_GROUP_SAMPLE.XREF_ZIPTOTRACT_RESIDENTIAL zt JOIN CENSUS_GALAXY__ZIP_CODE_TO_BLOCK_GROUP_SAMPLE.Xref_TractToZip_Residential tz ON zt.FromZipCode = tz.ToZipCode GROUP BY zt.FromZipCode ORDER BY event_cnt DESC LIMIT 1000;
SELECT m.MetricCategory, COUNT(*) AS event_cnt FROM CENSUS_GALAXY__ZIP_CODE_TO_BLOCK_GROUP_SAMPLE.DIM_CENSUSMETRICS m JOIN CENSUS_GALAXY__ZIP_CODE_TO_BLOCK_GROUP_SAMPLE.Fact_CensusValues_ACS2021 f ON m.MetricID = f.MetricID GROUP BY m.MetricCategory ORDER BY event_cnt DESC LIMIT 1000;
SELECT m.MetricCategory, SUM(f.CensusValue) AS total_quantity FROM CENSUS_GALAXY__ZIP_CODE_TO_BLOCK_GROUP_SAMPLE.DIM_CENSUSMETRICS m JOIN CENSUS_GALAXY__ZIP_CODE_TO_BLOCK_GROUP_SAMPLE.Fact_CensusValues_ACS2021 f ON m.MetricID = f.MetricID GROUP BY m.MetricCategory ORDER BY total_quantity DESC LIMIT 1000;
SELECT m.MetricID AS id_external FROM CENSUS_GALAXY__ZIP_CODE_TO_BLOCK_GROUP_SAMPLE.DIM_CENSUSMETRICS m WHERE COALESCE(m.MetricTableDesc, '') LIKE '%age%' or '%income%' or '%housing%' ORDER BY m.MetricID LIMIT 5;
SELECT m.MetricCategory, COUNT(*) AS hit_cnt FROM CENSUS_GALAXY__ZIP_CODE_TO_BLOCK_GROUP_SAMPLE.DIM_CENSUSMETRICS m WHERE COALESCE(m.MetricTableDesc, '') LIKE '%Median%' or '%Means%' GROUP BY m.MetricCategory ORDER BY hit_cnt DESC LIMIT 10;
SELECT g.PreferredStateName AS location, g.ZipCodeType AS category_topic, COUNT(*) AS event_cnt FROM CENSUS_GALAXY__ZIP_CODE_TO_BLOCK_GROUP_SAMPLE.LU_GEOGRAPHYEXPANDED g GROUP BY g.PreferredStateName, g.ZipCodeType HAVING COUNT(*) >= 5 ORDER BY event_cnt DESC LIMIT 20;
SELECT COUNT(DISTINCT t.ORG_ID) AS distinct_entity_cnt FROM DataManagementPlatform.原油商品量月动态表 t WHERE t.ORG_ID IS NOT NULL;
SELECT t.ORG_ID, COUNT(*) AS event_cnt FROM DataManagementPlatform.原油销售日报 t WHERE t.ORG_ID IS NOT NULL AND t.REPORT_FORM_DAILY_ID IS NOT NULL GROUP BY t.ORG_ID ORDER BY event_cnt DESC LIMIT 1000;
SELECT COUNT(*) AS event_cnt FROM `DataManagementPlatform`.`原油日产量(A8 2.0)` t WHERE t.ORDER_DATE >= '2024-01-01 00:00:00' AND t.ORDER_DATE < '2024-01-31 23:59:59';
SELECT t.BWART, COUNT(*) AS event_cnt FROM `DataManagementPlatform`.`原油日商品量(A8 2.0)` t WHERE t.BWART IS NOT NULL GROUP BY t.BWART ORDER BY event_cnt DESC LIMIT 1000;
SELECT t.ENERGY_SORT, SUM(t.MONTH_MERCHANDISE_VOLUME) AS total_amount FROM DataManagementPlatform.原油商品量月动态表 t WHERE t.ENERGY_SORT IS NOT NULL AND t.MONTH_MERCHANDISE_VOLUME IS NOT NULL GROUP BY t.ENERGY_SORT ORDER BY total_amount DESC LIMIT 1000;
SELECT t.REPORT_FORM_DAILY_ID, COUNT(DISTINCT t.ORG_ID) AS entity_cnt FROM `DataManagementPlatform`.`原油销售日报` t WHERE t.REPORT_FORM_DAILY_ID IS NOT NULL GROUP BY t.REPORT_FORM_DAILY_ID HAVING COUNT(DISTINCT t.ORG_ID) > 1 ORDER BY entity_cnt DESC LIMIT 3;
WITH a AS ( SELECT DISTINCT t.SGTXT FROM `DataManagementPlatform`.`原油日产量(A8 2.0)` t WHERE t.SGTXT IS NOT NULL AND t.ORDER_DATE >= '2025-01-01 00:00:00' AND t.ORDER_DATE < '2025-01-03 00:00:00' ), b AS ( SELECT DISTINCT t.SGTXT FROM `DataManagementPlatform`.`原油日产量(A8 2.0)` t WHERE t.SGTXT IS NOT NULL AND t.ORDER_DATE >= '2025-01-05 00:00:00' AND t.ORDER_DATE < '2025-01-07 00:00:00' ) SELECT COUNT(*) AS retained_entity_cnt FROM a JOIN b USING (SGTXT);
SELECT t.BWART, SUM(CASE WHEN t.ORDER_DATE >= '2025-01-01 00:00:00' AND t.ORDER_DATE < '2025-01-03 00:00:00' THEN 1 ELSE 0 END) AS curr_cnt, SUM(CASE WHEN t.ORDER_DATE >= '2025-01-05 00:00:00' AND t.ORDER_DATE < '2025-01-07 00:00:00' THEN 1 ELSE 0 END) AS prev_cnt, ( SUM(CASE WHEN t.ORDER_DATE >= '2025-01-01 00:00:00' AND t.ORDER_DATE < '2025-01-03 00:00:00' THEN 1 ELSE 0 END) - SUM(CASE WHEN t.ORDER_DATE >= '2025-01-05 00:00:00' AND t.ORDER_DATE < '2025-01-07 00:00:00' THEN 1 ELSE 0 END) ) AS delta_cnt FROM `DataManagementPlatform`.`原油日商品量(A8 2.0)` t WHERE t.BWART IS NOT NULL GROUP BY t.BWART ORDER BY delta_cnt DESC LIMIT 3;
WITH agg AS ( SELECT t.BWTAR AS topic, SUM(t.AMOUNT) AS amt FROM `DataManagementPlatform`.`原油月产量(A8 2.0)` t WHERE CAST(t.ORDER_DATE AS DATETIME) >= '2025-01-01 00:00:00' AND CAST(t.ORDER_DATE AS DATETIME) < '2025-02-01 00:00:00' AND t.BWTAR IS NOT NULL GROUP BY t.BWTAR ), tot AS ( SELECT SUM(amt) AS total_amt FROM agg ) SELECT topic, amt, amt / NULLIF((SELECT total_amt FROM tot), 0) AS amt_share FROM agg ORDER BY amt_share DESC;
WITH daily AS ( SELECT DATE( t.DATA_DATE) AS d, COUNT(*) AS cnt FROM `DataManagementPlatform`.`原油销售日报` t WHERE CAST(t.DATA_DATE AS DATETIME) >= '2025-01-21 00:00:00' AND CAST(t.DATA_DATE AS DATETIME) < '2025-01-28 00:00:00' GROUP BY d ), ma AS ( SELECT d, cnt, AVG(cnt) OVER (ORDER BY d ROWS BETWEEN 7 PRECEDING AND 1 PRECEDING) AS prev_7d_avg FROM daily ) SELECT d, cnt, prev_7d_avg FROM ma WHERE prev_7d_avg IS NOT NULL AND cnt > prev_7d_avg ORDER BY (cnt - prev_7d_avg) DESC;
SELECT t.UNIFY_TASK_ID, SUM(CASE WHEN t.APPROVAL_STATUS = 0 THEN 0 ELSE 1 END) AS hit_cnt, COUNT(*) AS total_cnt, SUM(CASE WHEN t.APPROVAL_STATUS = 0 THEN 0 ELSE 1 END) / COUNT(*) AS hit_ratio FROM DataManagementPlatform.原油销售日报 t WHERE t.UNIFY_TASK_ID IS NOT NULL GROUP BY t.UNIFY_TASK_ID ORDER BY hit_ratio DESC LIMIT 3;
SELECT t.COMPANY AS id_external FROM DataManagementPlatform.公司代码信息 t WHERE COALESCE(t.ZZTP_REMK, '') LIKE '%海外单位%' LIMIT 5;
WITH agg AS ( SELECT t.ENERGY_SORT AS topic, t.ORG_NAME AS entity_name, SUM(t.MONTH_MERCHANDISE_VOLUME) AS amt FROM DataManagementPlatform.原油商品量月动态表 t WHERE t.ENERGY_SORT IS NOT NULL AND t.ORG_NAME IS NOT NULL AND t.MONTH_MERCHANDISE_VOLUME IS NOT NULL GROUP BY t.ENERGY_SORT, t.ORG_NAME ), ranked AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY topic ORDER BY amt DESC, entity_name) AS rn FROM agg ) SELECT topic, entity_name, amt FROM ranked WHERE rn = 1 ORDER BY amt DESC;
SELECT t.PROJ_TYPE AS category_topic, COUNT(*) AS event_cnt FROM DataManagementPlatform.原油销售日报 t WHERE str_to_date(t.DATA_DATE, '%Y-%m-%d') >= '2025-01-01' AND str_to_date(t.DATA_DATE, '%Y-%m-%d') < '2025-03-01' AND t.REMARKS = 1 GROUP BY t.PROJ_TYPE ORDER BY event_cnt DESC LIMIT 10;
SELECT t.DATA_REGION AS location, t.ENERGY_SORT AS category_topic, COUNT(*) AS event_cnt FROM DataManagementPlatform.原油商品量月动态表 t WHERE t.DATA_REGION IS NOT NULL AND t.ENERGY_SORT IS NOT NULL GROUP BY t.DATA_REGION, t.ENERGY_SORT HAVING COUNT(*) >= 10 ORDER BY event_cnt DESC LIMIT 20;
